import assert from 'node:assert/strict'
import { writeFile } from 'node:fs/promises'
import { spawnSync } from 'node:child_process'
import { join, resolve } from 'node:path'

const root = import.meta.dirname
const comparator = resolve('scripts/team-performance/compare-team-performance.mjs')
const metric = (value, count = 3) => ({ count, p50: value, p95: value, p99: value })
const document = value => ({ summary: [{ scenario: 'host-boot', samples: 3, metrics: { hostBootMs: value } }] })
const fixtures = {
  before: document(metric(10)), same: document(metric(10)), slower: document(metric(20)),
  unavailable: document(metric(null, 0)), zero: document(metric(0)),
}
for (const [key, value] of Object.entries(fixtures)) await writeFile(join(root, `${key}.json`), JSON.stringify(value))
const results = []
for (const [before, after] of [['before', 'same'], ['before', 'slower'], ['before', 'unavailable'], ['zero', 'slower']]) {
  const result = spawnSync(process.execPath, [comparator, '--json', '--max-regression', '20', join(root, `${before}.json`), join(root, `${after}.json`)], { encoding: 'utf8' })
  assert.equal(result.signal, null)
  const report = JSON.parse(result.stdout)
  results.push({ before, after, exitCode: result.status, rows: report.rows.length, regressions: report.regressions.length,
    missingMetricsInAfter: report.missingMetricsInAfter })
}
assert.equal(results[0].exitCode, 0)
assert.equal(results[1].exitCode, 1)
await writeFile(join(root, 'compare-check-result.json'), JSON.stringify(results, null, 2) + '\n')
console.log(JSON.stringify(results, null, 2))

