    const timer = setTimeout(() => { dispose(); reject(new Error('benchmark Agent did not become idle within 20 seconds')) }, 20_000)
    const dispose = ctx.on('agent/status', ({ agent: subject, status }: { agent: unknown; status: string }) => {
      if (subject !== agent || status !== 'idle') return
      clearTimeout(timer)
      dispose()
      resolveIdle()
    })
  })
}

async function waitForFirstModelRequest(adapter: TextAdapter): Promise<void> {
  await waitForModelRequest(adapter, 1)
}

async function waitForModelRequest(adapter: TextAdapter, expectedCount: number): Promise<void> {
  const deadline = now() + 20_000
  while (adapter.requests.length < expectedCount) {
    if (now() >= deadline) throw new Error(`benchmark Agent did not request model turn ${expectedCount} within 20 seconds`)
    await new Promise<void>(resolveRequest => setImmediate(resolveRequest))
  }
}

async function collaborationAgentTurnSample(sample: number, commits: { team: string; harness: string }): Promise<Sample> {
  const startedAt = new Date().toISOString()
  const host = await mount()
  const adapter = new TextAdapter()
  const releaseAdapter = host.ctx.llm.registerAdapter(['mock'], adapter)
  try {
    const project = await host.ctx.agentTeam.createProject({ requestId: requestId(`baseline:agent-project:${sample}`), workspaceId, name: 'agent-turn', description: 'Performance benchmark' })
    const receiver = await addMember(host.ctx, `baseline-agent-turn-${sample}`, project.project.projectRef)
    let phase: 'cold' | 'warm' = 'cold'
    let coldNoticeQueuedAt: number | null = null
    let warmNoticeQueuedAt: number | null = null
    const recordNoticeQueued = (): void => {
      if (phase === 'cold') coldNoticeQueuedAt ??= now()
      else warmNoticeQueuedAt ??= now()
    }
    const originalSteer = receiver.agent.steer.bind(receiver.agent)
    const originalFollowup = receiver.agent.followup.bind(receiver.agent)
    receiver.agent.steer = (message: unknown) => { recordNoticeQueued(); return originalSteer(message) }
    receiver.agent.followup = (message: unknown) => { recordNoticeQueued(); return originalFollowup(message) }
    const begin = now()
    const started = await host.ctx.agentTeam.startThread({ kind: 'discussion', requestId: requestId(`baseline:agent-thread:${sample}`), workspaceId,
      projectRef: project.project.projectRef, body: `@${receiver.actor.handle} run the benchmark`, })
    if (started.kind !== 'committed') throw new Error(`agent-turn benchmark Thread did not commit: ${started.kind}`)
    const committedMs = elapsed(begin)
    const requestWaitBegin = now()
    await waitForFirstModelRequest(adapter)
    const requestMs = elapsed(requestWaitBegin)
    const idleBegin = now()
    await waitForAgentIdle(host.ctx, receiver.agent)
    const idleMs = elapsed(idleBegin)
    const coldRequestAt = adapter.requestTimes[0]
    const coldNoticeToRequestMs = coldNoticeQueuedAt !== null && coldRequestAt !== undefined ? coldRequestAt - coldNoticeQueuedAt : null
    const coldTriggerToNoticeQueuedMs = coldNoticeQueuedAt === null ? null : coldNoticeQueuedAt - begin
    const warmBegin = now()
    phase = 'warm'
    const warmStarted = await host.ctx.agentTeam.reply({ requestId: requestId(`baseline:agent-warm-reply:${sample}`), workspaceId,
      threadRef: started.thread.threadRef, baseRevision: started.thread.revision, body: `@${receiver.actor.handle} run the warm benchmark`, })
    if (warmStarted.kind !== 'committed') throw new Error(`agent-turn warm reply did not commit: ${warmStarted.kind}`)
    const warmCommittedMs = elapsed(warmBegin)
    const warmRequestWaitBegin = now()
    await waitForModelRequest(adapter, 2)
    const warmRequestMs = elapsed(warmRequestWaitBegin)
    const warmIdleBegin = now()
    await waitForAgentIdle(host.ctx, receiver.agent)
    const warmIdleMs = elapsed(warmIdleBegin)
    const warmRequestAt = adapter.requestTimes[1]
    const warmNoticeToRequestMs = warmNoticeQueuedAt !== null && warmRequestAt !== undefined ? warmRequestAt - warmNoticeQueuedAt : null
    const warmTriggerToNoticeQueuedMs = warmNoticeQueuedAt === null ? null : warmNoticeQueuedAt - warmBegin
    return { runId, scenario: 'collaboration-agent-turn', sample, phase: sample === 0 ? 'warmup' : 'measure', startedAt,
      teamCommit: commits.team, harnessCommit: commits.harness, node: process.version,
      workload: { receiver: receiver.memberId, model: 'mock', response: 'fixed-text', modelRequests: adapter.requests.length, warmMode: 'same-agent-same-host' },
      stages: { triggerCommitMs: committedMs, commitToModelRequestMs: requestMs, modelRequestToAgentIdleMs: idleMs,
        triggerToNoticeQueuedMs: coldTriggerToNoticeQueuedMs, noticeQueuedToModelRequestMs: coldNoticeToRequestMs,
        triggerToAgentIdleMs: committedMs + requestMs + idleMs, warmTriggerCommitMs: warmCommittedMs,
        warmCommitToModelRequestMs: warmRequestMs, warmModelRequestToAgentIdleMs: warmIdleMs,
        warmTriggerToNoticeQueuedMs, warmNoticeQueuedToModelRequestMs: warmNoticeToRequestMs,
        warmTriggerToAgentIdleMs: warmCommittedMs + warmRequestMs + warmIdleMs },
      ids: { requestId: started.receipt.requestId, operationId: started.receipt.operationId, warmRequestId: warmStarted.receipt.requestId,
        warmOperationId: warmStarted.receipt.operationId, noticeMessageId: null, turnId: null, agentSessionId: receiver.agent.id },
      counters: { modelRequests: adapter.requests.length, responseBytes: Buffer.byteLength('Benchmark response.'), coldTurns: 1, warmTurns: 1 } }
  } finally {
    releaseAdapter()
    await host.dispose()
  }
}

