import { execFile as execFileCallback } from 'node:child_process'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { randomUUID } from 'node:crypto'
import { join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'

const root = resolve(fileURLToPath(new URL('../..', import.meta.url)))
const execFile = promisify(execFileCallback)
const samples = process.env.DSH_BENCH_MATRIX_SAMPLES ?? process.env.DSH_BENCH_SAMPLES ?? '3'
const warmups = process.env.DSH_BENCH_MATRIX_WARMUPS ?? process.env.DSH_BENCH_WARMUPS ?? '1'
const defaultCases = [
  'member-activation-batch:8:1',
  'ledger-read-memory:1:1', 'ledger-read-memory:20:1', 'ledger-read-memory:100:1',
  'ledger-replay-sqlite:1:1', 'ledger-replay-sqlite:20:1', 'ledger-replay-sqlite:100:1',
  'collaboration-fanout:1:1', 'collaboration-fanout:1:2', 'collaboration-fanout:1:4',
  'collaboration-fanout:1:8', 'collaboration-fanout:20:4', 'collaboration-fanout:1:32',
  'session-fold:10000:1', 'session-replay-jsonl:10000:1',
]
const cases = (process.env.DSH_BENCH_MATRIX_CASES ?? defaultCases.join(','))
  .split(',').map(value => value.trim()).filter(Boolean).map((value, index) => {
    const [scenario, threads, followers] = value.split(':')
    if (scenario === undefined || threads === undefined || followers === undefined
      || !Number.isInteger(Number(threads)) || !Number.isInteger(Number(followers))) {
      throw new Error(`Invalid matrix case '${value}' at index ${index}; use scenario:threads:followers`)
    }
    return { scenario, threads: Number(threads), followers: Number(followers) }
  })
const runId = `${new Date().toISOString().replaceAll(/[:.]/g, '-')}-${randomUUID().slice(0, 8)}`
const outputRoot = resolve(root, 'artifacts/team-perf/matrices', runId)
const baseline = join(root, 'scripts/team-performance/team-performance-baseline.ts')

await mkdir(outputRoot, { recursive: true })
await writeFile(join(outputRoot, 'manifest.json'), `${JSON.stringify({ runId, startedAt: new Date().toISOString(), samples, warmups, cases, node: process.version }, null, 2)}\n`)

const results = []
for (const [index, current] of cases.entries()) {
  const env = {
    ...process.env,
    DSH_BENCH_TEAM: '1', DSH_BENCH_SAMPLES: samples, DSH_BENCH_WARMUPS: warmups,
    DSH_BENCH_SCENARIOS: current.scenario, DSH_BENCH_THREADS: String(current.threads), DSH_BENCH_FOLLOWERS: String(current.followers),
    ...(current.scenario === 'member-activation-batch' ? { DSH_BENCH_MEMBERS: String(current.threads) } : {}),
    ...(current.scenario === 'session-fold' || current.scenario === 'session-replay-jsonl' ? { DSH_BENCH_SESSION_EVENTS: String(current.threads) } : {}),
  }
  try {
    const result = await execFile(process.execPath, ['--import', 'tsx', baseline], { cwd: root, env, maxBuffer: 4 * 1024 * 1024 })
    const match = result.stdout.match(/"outputRoot":\s*"([^"]+)"/)
    if (match?.[1] === undefined) throw new Error('benchmark output did not report outputRoot')
    const summary = JSON.parse(await readFile(join(match[1], 'summary.json'), 'utf8'))
    results.push({ index, ...current, status: 'passed', outputRoot: match[1], summary })
  } catch (error) {
    results.push({ index, ...current, status: 'failed', error: error instanceof Error ? error.message : String(error) })
    await writeFile(join(outputRoot, 'results.json'), `${JSON.stringify({ runId, results }, null, 2)}\n`)
    throw new Error(`matrix case ${index} (${current.scenario}:${current.threads}:${current.followers}) failed`, { cause: error })
  }
  await writeFile(join(outputRoot, 'results.json'), `${JSON.stringify({ runId, results }, null, 2)}\n`)
}

console.log(JSON.stringify({ runId, outputRoot, results }, null, 2))

    await host.dispose()
  }
}

async function waitForAgentIdle(ctx: any, agent: any): Promise<void> {
  if (agent.status === 'idle') return
  await new Promise<void>((resolveIdle, reject) => {
    const timer = setTimeout(() => { dispose(); reject(new Error('benchmark Agent did not become idle within 20 seconds')) }, 20_000)
    const dispose = ctx.on('agent/status', ({ agent: subject, status }: { agent: unknown; status: string }) => {
      if (subject !== agent || status !== 'idle') return
      clearTimeout(timer)
      dispose()
      resolveIdle()
    })
  })
}

async function waitForFirstModelRequest(adapter: TextAdapter): Promise<void> {
  await waitForModelRequest(adapter, 1)
}

async function waitForModelRequest(adapter: TextAdapter, expectedCount: number): Promise<void> {
  const deadline = now() + 20_000
  while (adapter.requests.length < expectedCount) {
    if (now() >= deadline) throw new Error(`benchmark Agent did not request model turn ${expectedCount} within 20 seconds`)
    await new Promise<void>(resolveRequest => setImmediate(resolveRequest))
  }
}

async function collaborationAgentTurnSample(sample: number, commits: { team: string; harness: string }): Promise<Sample> {
  const startedAt = new Date().toISOString()
  const host = await mount()
  const adapter = new TextAdapter()
  const releaseAdapter = host.ctx.llm.registerAdapter(['mock'], adapter)
  try {
    const project = await host.ctx.agentTeam.createProject({ requestId: requestId(`baseline:agent-project:${sample}`), workspaceId, name: 'agent-turn', description: 'Performance benchmark' })
    const receiver = await addMember(host.ctx, `baseline-agent-turn-${sample}`, project.project.projectRef)
    let phase: 'cold' | 'warm' = 'cold'
    let coldNoticeQueuedAt: number | null = null
    let warmNoticeQueuedAt: number | null = null
    const recordNoticeQueued = (): void => {
      if (phase === 'cold') coldNoticeQueuedAt ??= now()
      else warmNoticeQueuedAt ??= now()
    }
    const originalSteer = receiver.agent.steer.bind(receiver.agent)
    const originalFollowup = receiver.agent.followup.bind(receiver.agent)
    receiver.agent.steer = (message: unknown) => { recordNoticeQueued(); return originalSteer(message) }
    receiver.agent.followup = (message: unknown) => { recordNoticeQueued(); return originalFollowup(message) }
    const begin = now()
    const started = await host.ctx.agentTeam.startThread({ kind: 'discussion', requestId: requestId(`baseline:agent-thread:${sample}`), workspaceId,
      projectRef: project.project.projectRef, body: `@${receiver.actor.handle} run the benchmark`, })
    if (started.kind !== 'committed') throw new Error(`agent-turn benchmark Thread did not commit: ${started.kind}`)
    const committedMs = elapsed(begin)
    const requestWaitBegin = now()
    await waitForFirstModelRequest(adapter)
    const requestMs = elapsed(requestWaitBegin)
    const idleBegin = now()
    await waitForAgentIdle(host.ctx, receiver.agent)
    const idleMs = elapsed(idleBegin)
    const coldRequestAt = adapter.requestTimes[0]
    const coldNoticeToRequestMs = coldNoticeQueuedAt !== null && coldRequestAt !== undefined ? coldRequestAt - coldNoticeQueuedAt : null
    const coldTriggerToNoticeQueuedMs = coldNoticeQueuedAt === null ? null : coldNoticeQueuedAt - begin
    const warmBegin = now()
    phase = 'warm'
    const warmStarted = await host.ctx.agentTeam.reply({ requestId: requestId(`baseline:agent-warm-reply:${sample}`), workspaceId,
      threadRef: started.thread.threadRef, baseRevision: started.thread.revision, body: `@${receiver.actor.handle} run the warm benchmark`, })
    if (warmStarted.kind !== 'committed') throw new Error(`agent-turn warm reply did not commit: ${warmStarted.kind}`)
    const warmCommittedMs = elapsed(warmBegin)
    const warmRequestWaitBegin = now()
    await waitForModelRequest(adapter, 2)
    const warmRequestMs = elapsed(warmRequestWaitBegin)
    const warmIdleBegin = now()
    await waitForAgentIdle(host.ctx, receiver.agent)
    const warmIdleMs = elapsed(warmIdleBegin)
    const warmRequestAt = adapter.requestTimes[1]
    const warmNoticeToRequestMs = warmNoticeQueuedAt !== null && warmRequestAt !== undefined ? warmRequestAt - warmNoticeQueuedAt : null
    const warmTriggerToNoticeQueuedMs = warmNoticeQueuedAt === null ? null : warmNoticeQueuedAt - warmBegin
    return { runId, scenario: 'collaboration-agent-turn', sample, phase: sample === 0 ? 'warmup' : 'measure', startedAt,
      teamCommit: commits.team, harnessCommit: commits.harness, node: process.version,
      workload: { receiver: receiver.memberId, model: 'mock', response: 'fixed-text', modelRequests: adapter.requests.length, warmMode: 'same-agent-same-host' },
      stages: { triggerCommitMs: committedMs, commitToModelRequestMs: requestMs, modelRequestToAgentIdleMs: idleMs,
        triggerToNoticeQueuedMs: coldTriggerToNoticeQueuedMs, noticeQueuedToModelRequestMs: coldNoticeToRequestMs,
        triggerToAgentIdleMs: committedMs + requestMs + idleMs, warmTriggerCommitMs: warmCommittedMs,
        warmCommitToModelRequestMs: warmRequestMs, warmModelRequestToAgentIdleMs: warmIdleMs,
        warmTriggerToNoticeQueuedMs, warmNoticeQueuedToModelRequestMs: warmNoticeToRequestMs,
        warmTriggerToAgentIdleMs: warmCommittedMs + warmRequestMs + warmIdleMs },
      ids: { requestId: started.receipt.requestId, operationId: started.receipt.operationId, warmRequestId: warmStarted.receipt.requestId,
        warmOperationId: warmStarted.receipt.operationId, noticeMessageId: null, turnId: null, agentSessionId: receiver.agent.id },
      counters: { modelRequests: adapter.requests.length, responseBytes: Buffer.byteLength('Benchmark response.'), coldTurns: 1, warmTurns: 1 } }
  } finally {
    releaseAdapter()
    await host.dispose()
  }
}

// Explicit benchmark entry point for Team performance work.
// Normal development and test commands do not run this file.
import { execFile as execFileCallback } from 'node:child_process'
import { randomUUID } from 'node:crypto'
import { appendFile, mkdir, readFile, readdir, stat, writeFile } from 'node:fs/promises'
import { mkdtemp, rm } from 'node:fs/promises'
import { performance } from 'node:perf_hooks'
import { join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { promisify } from 'node:util'
import { Context } from '@deepseek-ai/cordis'
import { brotliCompressSync, gzipSync } from 'node:zlib'
import { ToolCallId, LlmAdapter } from '@deepseek-ai/dsh-llm'
import type { GenerateOptions, StreamChunk } from '@deepseek-ai/dsh-llm'
import { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import * as JsonlSessionPersistence from '@deepseek-ai/dsh-session-persistence-jsonl'
import { sessionFormatCatalog } from '@deepseek-ai/dsh-session-format-catalog'
import { SessionId } from '@deepseek-ai/dsh-session'
import { harnessDir } from '../../scripts/harness-dir.mjs'
import { agentTeamHumanActor, AgentTeamLedger } from '../../packages/agent-team/src/ledger.ts'
import { foldTeamContextProjection } from '../../packages/agent-team/src/context-projection.ts'
import { advanceSessionEventCursor, initSessionEventCursor, type SessionEventFold } from '../../packages/agent-team/src/session-event-cursor.ts'
import { mountTeamMemberHost, provideQuietTokenMeter } from '../../packages/agent-team/tests/helpers/team-host-fixture.ts'
import { addLedgerMember, alpha, harness, ledgerAtBoot, makeOwner, sqliteHarness } from '../../packages/agent-team/tests/helpers/host-harness.ts'
import type { AgentTeamMemberActor, AgentTeamRequestId } from '../../packages/agent-team/src/types.ts'

if (process.env.DSH_BENCH_TEAM !== '1') {
  console.error('Set DSH_BENCH_TEAM=1 to run the Team performance baseline.')
  process.exit(0)
}

const root = resolve(fileURLToPath(new URL('../..', import.meta.url)))
const harnessRoot = harnessDir
const execFile = promisify(execFileCallback)
const workspaceId = WorkspaceId('workspace:fixture')
const requestId = (value: string): AgentTeamRequestId => value as AgentTeamRequestId
const samplesPerScenario = Number(process.env.DSH_BENCH_SAMPLES ?? 3)
const warmupsPerScenario = Number(process.env.DSH_BENCH_WARMUPS ?? 1)
if (!Number.isInteger(samplesPerScenario) || samplesPerScenario < 1) throw new Error('DSH_BENCH_SAMPLES must be a positive integer')
if (!Number.isInteger(warmupsPerScenario) || warmupsPerScenario < 0) throw new Error('DSH_BENCH_WARMUPS must be a non-negative integer')
const followerCount = Number(process.env.DSH_BENCH_FOLLOWERS ?? 1)
const threadCount = Number(process.env.DSH_BENCH_THREADS ?? 1)
const sessionEventCount = Number(process.env.DSH_BENCH_SESSION_EVENTS ?? 10_000)
const sessionCompression = process.env.DSH_BENCH_SESSION_COMPRESSION ?? 'zstd'
const memberCount = Number(process.env.DSH_BENCH_MEMBERS ?? 8)
if (!Number.isInteger(followerCount) || followerCount < 1) throw new Error('DSH_BENCH_FOLLOWERS must be a positive integer')
if (!Number.isInteger(threadCount) || threadCount < 1) throw new Error('DSH_BENCH_THREADS must be a positive integer')
if (!Number.isInteger(sessionEventCount) || sessionEventCount < 2) throw new Error('DSH_BENCH_SESSION_EVENTS must be an integer >= 2')
if (sessionCompression !== 'zstd' && sessionCompression !== 'none') throw new Error('DSH_BENCH_SESSION_COMPRESSION must be zstd or none')
