import { readFile } from 'node:fs/promises'

const usage = 'Usage: node scripts/team-performance/compare-team-performance.mjs [--json] [--max-regression <percent>] <before-summary-or-matrix> <after-summary-or-matrix>'
const rawArgs = process.argv.slice(2)
const json = rawArgs.includes('--json')
const args = rawArgs.filter(value => value !== '--json')
let maxRegression
const positional = []
for (let index = 0; index < args.length; index += 1) {
  const value = args[index]
  if (value === '--max-regression') {
    const next = args[++index]
    maxRegression = Number(next)
  } else if (value.startsWith('--max-regression=')) {
    maxRegression = Number(value.slice('--max-regression='.length))
  } else {
    positional.push(value)
  }
}
if (positional.length !== 2 || (maxRegression !== undefined && (!Number.isFinite(maxRegression) || maxRegression < 0))) {
  console.error(usage)
  process.exit(2)
}

async function readJson(path) {
  return JSON.parse(await readFile(path, 'utf8'))
}

function summaryEntries(document, source) {
  if (Array.isArray(document.summary)) return document.summary.map(entry => ({ key: entry.scenario, summary: entry }))
  if (Array.isArray(document.results)) {
    return document.results.flatMap(result => {
      const summaries = result.summary?.summary
      if (!Array.isArray(summaries)) return []
      const key = `${result.scenario}:${result.threads}:${result.followers}`
      return summaries.map(summary => ({ key, summary }))
    })
  }
  throw new Error(`${source} is neither a run summary.json nor a matrix results.json`)
}

async function load(path) {
  return summaryEntries(await readJson(path), path)
}

function metricRows(beforeEntries, afterEntries) {
  const before = new Map(beforeEntries.map(entry => [entry.key, entry.summary]))
  const after = new Map(afterEntries.map(entry => [entry.key, entry.summary]))
  const rows = []
  const missingInAfter = []
  const missingInBefore = []
  const invalidMetrics = []
  const validMetric = (metric) => metric !== undefined
    && metric.count > 0
    && ['p50', 'p95', 'p99'].every(percentile => typeof metric[percentile] === 'number' && Number.isFinite(metric[percentile]))
  for (const [key, beforeSummary] of before) {
    const afterSummary = after.get(key)
    if (afterSummary === undefined) continue
    const metrics = new Set([...Object.keys(beforeSummary.metrics ?? {}), ...Object.keys(afterSummary.metrics ?? {})])
    for (const metric of metrics) {
      const inBefore = beforeSummary.metrics?.[metric] !== undefined
      const inAfter = afterSummary.metrics?.[metric] !== undefined
      if (inBefore && !inAfter) missingInAfter.push({ key, metric })
      if (!inBefore && inAfter) missingInBefore.push({ key, metric })
    }
    for (const metric of metrics) {
      const beforeMetric = beforeSummary.metrics?.[metric]
      const afterMetric = afterSummary.metrics?.[metric]
      if (beforeMetric !== undefined && !validMetric(beforeMetric)) invalidMetrics.push({ key, metric, side: 'before', reason: 'no valid measured percentiles' })
      if (afterMetric !== undefined && !validMetric(afterMetric)) invalidMetrics.push({ key, metric, side: 'after', reason: 'no valid measured percentiles' })
      for (const percentile of ['p50', 'p95', 'p99']) {
        const beforeValue = beforeSummary.metrics?.[metric]?.[percentile]
        const afterValue = afterSummary.metrics?.[metric]?.[percentile]
        if (typeof beforeValue !== 'number' || typeof afterValue !== 'number') continue
        const deltaMs = afterValue - beforeValue
        const deltaPercent = beforeValue === 0 ? null : (deltaMs / beforeValue) * 100
        rows.push({ key, metric, percentile, before: beforeValue, after: afterValue, deltaMs, deltaPercent,
          zeroBaselineIncrease: beforeValue === 0 && afterValue > 0 })
      }
    }
  }
  return { rows, missingInAfter, missingInBefore, invalidMetrics }
}

const beforeEntries = await load(positional[0])
const afterEntries = await load(positional[1])
const beforeKeys = new Set(beforeEntries.map(entry => entry.key))
const afterKeys = new Set(afterEntries.map(entry => entry.key))
const metricComparison = metricRows(beforeEntries, afterEntries)
const { rows } = metricComparison
const regressions = maxRegression === undefined
  ? []
  : rows.filter(row => row.zeroBaselineIncrease || (row.deltaPercent !== null && row.deltaPercent > maxRegression))
const report = {
  before: positional[0],
  after: positional[1],
  maxRegressionPercent: maxRegression ?? null,
  missingInAfter: [...beforeKeys].filter(key => !afterKeys.has(key)),
  missingInBefore: [...afterKeys].filter(key => !beforeKeys.has(key)),
  missingMetricsInAfter: metricComparison.missingInAfter,
  missingMetricsInBefore: metricComparison.missingInBefore,
  invalidMetrics: metricComparison.invalidMetrics,
  rows,
  regressions,
}

if (json) {
  console.log(JSON.stringify(report, null, 2))
} else {
  console.log(`before: ${report.before}`)
  console.log(`after:  ${report.after}`)
  if (report.missingInAfter.length > 0) console.log(`missing in after: ${report.missingInAfter.join(', ')}`)
  if (report.missingInBefore.length > 0) console.log(`missing in before: ${report.missingInBefore.join(', ')}`)
  if (report.missingMetricsInAfter.length > 0) console.log(`missing metrics in after: ${report.missingMetricsInAfter.map(entry => `${entry.key}.${entry.metric}`).join(', ')}`)
  if (report.missingMetricsInBefore.length > 0) console.log(`missing metrics in before: ${report.missingMetricsInBefore.map(entry => `${entry.key}.${entry.metric}`).join(', ')}`)
  if (report.invalidMetrics.length > 0) console.log(`invalid metrics: ${report.invalidMetrics.map(entry => `${entry.side} ${entry.key}.${entry.metric} (${entry.reason})`).join(', ')}`)
  for (const row of rows) {
    const delta = row.zeroBaselineIncrease ? 'from zero' : row.deltaPercent === null ? 'n/a' : `${row.deltaPercent >= 0 ? '+' : ''}${row.deltaPercent.toFixed(1)}%`
    console.log(`${row.key} ${row.metric}.${row.percentile}: ${row.before.toFixed(3)}ms -> ${row.after.toFixed(3)}ms (${delta})`)
  }
  if (maxRegression !== undefined) console.log(`regressions over ${maxRegression}%: ${regressions.length}`)
}
if (maxRegression !== undefined && (regressions.length > 0 || report.missingInAfter.length > 0 || report.missingInBefore.length > 0
  || report.missingMetricsInAfter.length > 0 || report.missingMetricsInBefore.length > 0 || report.invalidMetrics.length > 0)) process.exitCode = 1

  const material = this.requireLedger().notificationSnapshot(member.memberId)
  const notifications = material.threads
  const mainNotifications = material.main
  const scope = this.memberScope(member.memberId, agent.id)
  const causeText = this.notificationCauseText(cause)
  if (notifications.length === 0 && mainNotifications.length === 0) {
    this.dropInboxCoverage(member.memberId)
    this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${scope} cause ${causeText}: the Member has no unread Team facts`)
    return
  }
  // Any ordinary next-turn input already queued (a rollover's or recovery's
  // carried messages) forces sequencing regardless of the caller: a steer
  // would claim the nearest step boundary and leapfrog the carried turn.
  if (!sequenced) {
    sequenced = agent.inbox.nextTurn.some(message => message.source.kind === 'user')
  }
  const previous = this.inboxNoticeDeliveries.get(member.memberId)
  const plan = this.inboxDeliveryPlan(notifications, mainNotifications, previous)
  const facts = this.notificationIdentity(notifications, mainNotifications)
  // An unchanged rederivation spends no attempt: the delivery already made
  // for these facts stands, which is what keeps a repeated commit's logging
  // bounded.
  if (plan.trigger === undefined) {
    this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${scope} cause ${causeText}: ${plan.signature === ''
      ? 'the Member has no unread Team facts'
      : `the same unread facts (${facts}) already have a delivery attempt`}`)
    return
  }
  const pending = [...agent.inbox.nextStep, ...agent.inbox.nextTurn]
  // steerResume already combines the recovery instruction and these durable
  // facts. Its synchronous running transition must not replace that notice.
  if (pending.some(message => this.isRecoveryNotice(message))) {
    this.coverInboxFacts(member.memberId, plan)
    this.ctx.logger.info(`agent-team: Team Inbox notice carried by the queued recovery instruction for ${scope} cause ${causeText} (${facts}): queued with that recovery instruction, not yet read by the model`)
    return
  }
  const existingInboxHint = pending.find(message => this.isInboxNotice(message))
  if (existingInboxHint !== undefined) this.removeExpectedTeamWake(agent, existingInboxHint)
  const notice = this.notificationText(agent, notifications, member.memberId, mainNotifications, plan)
  const hint = createUserMessage({
    content: [{ type: 'text', text: notice.text }],
    source: { kind: AGENT_TEAM_PLUGIN_ID, form: 'notice', summary: TEAM_INBOX_NOTICE_SUMMARY, teamFacts: teamMessageSurface(notice.text, notice.messages, notice.activities) },
  })
  this.trackTeamWake(agent, hint)
  const attempt = this.beginInboxDelivery(member.memberId, plan, notice.undelivered)
  try {
    // Steer normally claims the nearest step boundary — which would
    // preempt carried input that a swap or crash recovery queued as
    // ordinary next-turn messages. The sequenced mode enqueues the
    // rederived Inbox as its own follow-up turn instead, so the delivery
    // order stays carried input → rederived Inbox.
    if (sequenced) agent.followup(hint)
    else agent.steer(hint)
  } catch (error) {
    this.dropInboxCoverage(member.memberId)
    if (error instanceof AgentTeamInvariantError) throw error
    this.ctx.logger.warn(`agent-team: Team Inbox notice delivery failed for ${scope} cause ${causeText} attempt ${attempt} (${facts}): ${failureDetail(error)}; the operation is committed and stands, and the failed delivery stands as an attempt so the next fact touching this Member rederives and retries it`)
    return
  }
  this.ctx.logger.info(`agent-team: Team Inbox notice queued for ${scope} cause ${causeText} attempt ${attempt} delivery ${plan.trigger} lane '${sequenced ? 'follow-up turn' : 'next step'}' (${facts}): queued for the Member's next step, not yet read by the model`)
}

/**
 * One line per automatic-recovery state change (classified family, counted occurrence, armed wait, fired wakeup, stand-down, end of tracking),
 * so no stop is silent and the automatic path is explainable without debug output.
 */
private reportRecovery(fact: RecoveryFact): void {
  const scope = this.memberScope(fact.memberId)
  if (fact.kind === 'scheduled') {
    this.ctx.logger.info(`agent-team: automatic recovery scheduled for ${scope} errorKind '${fact.errorKind}' occurrence ${fact.consecutiveFailures}/${fact.maxConsecutiveErrors} wait ${fact.delayMs}ms`)
    return
  }
  if (fact.kind === 'woke') {
    this.ctx.logger.debug(`agent-team: automatic recovery wait elapsed for ${scope} after ${fact.consecutiveFailures} consecutive recoverable error(s): attempting the automatic continuation`)
    return
  }
  if (fact.kind === 'stood-down') {
    this.ctx.logger.warn(`agent-team: automatic recovery stood down for ${scope} after ${fact.consecutiveFailures}/${fact.maxConsecutiveErrors} consecutive '${fact.errorKind}' errors: leaving the Member in error for the operator, with no further automatic wakeup until a clean turn or a manual recovery`)
    return
  }
  this.ctx.logger.info(`agent-team: automatic recovery cleared for ${scope} reason '${fact.reason}' after ${fact.consecutiveFailures} consecutive recoverable error(s) with ${fact.pendingWakes} pending wakeup(s)${fact.stoodDown ? ', stood down' : ''}${fact.detail === undefined ? '' : `: ${fact.detail}`}`)
}

private isInboxNotice(message: UserMessage): boolean {
  const source = message.source
  return isAgentTeamSource(source)
    && source.form === 'notice' && source.summary === TEAM_INBOX_NOTICE_SUMMARY
}

/** Every Team-authored notice, including the acceptance reminder: a queued one is Host context, not the Member's own unfinished input, so it must not pin the current generation. */
private isTeamWake(message: UserMessage): boolean {
  return this.isInboxNotice(message) || this.isRecoveryNotice(message) || isAcceptanceNotice(message)
