  await makeOwner(ledger, project.projectRef, member.member.memberId)
  for (let i=0;i<100;i++) {
    const started = (await ledger.startThread({ kind:'discussion',requestId:requestId(`control-thread-${i}`),actor:agentTeamHumanActor(),workspaceId:alpha,projectRef:project.projectRef,body:'Control Thread' })).value
    await ledger.changeAttention({ requestId:requestId(`control-follow-${i}`),actor:member.actor,workspaceId:alpha,threadRef:started.thread.threadRef,action:'follow' })
